-- Periodic assessment v2, five badges, admin-managed Learn articles and the
-- consultation directory.
--
--  1. Questionnaire: an "active" switch per section (the admin can hide the
--     clinical measurements section), question styles, images and
--     show-if rules, and the revised questionnaire (no responses existed).
--  2. Assessment rounds are named Mid Year / Year End, not Spring / Fall.
--  3. Measurement source on the profile.
--  4. Badges: only Aqua Achiever, Active Aura, Smart Eater, Heart Minded and
--     Curious Learner remain; article reads are recorded for Curious Learner.
--  5. Learn articles can be hidden, given an uploaded cover and ordered; admins
--     can add and edit them.
--  6. Professionals and the 24/7 University Health Centre number.

-- ---------------------------------------------------------------------------
-- 1. Questionnaire
-- ---------------------------------------------------------------------------
alter table public.assessment_domains add column if not exists active boolean not null default true;
alter table public.assessment_questions add column if not exists style text;
alter table public.assessment_questions add column if not exists image text;
alter table public.assessment_questions add column if not exists show_if jsonb;
alter table public.assessment_questions drop constraint if exists assessment_questions_kind_check;
alter table public.assessment_questions add constraint assessment_questions_kind_check
  check (kind in ('single', 'multi', 'scale', 'number', 'text', 'profile'));
alter table public.assessment_questions drop constraint if exists assessment_questions_prefill_check;
alter table public.assessment_questions add constraint assessment_questions_prefill_check
  check (prefill in ('height_cm', 'weight_kg', 'waist_cm', 'hip_cm', 'accommodation', 'sbp', 'dbp', 'fbg', 'tg', 'chol'));

-- No student has answered the first version, so it is replaced outright.
delete from public.assessment_questions
where not exists (select 1 from public.assessments a where a.answers ? assessment_questions.id);

-- Generated by supabase/seed/build_questionnaire.py. Do not edit by hand.
insert into public.assessment_domains (id, title, blurb, icon, position, active) values
  (1, 'Physical and cardiometabolic health', 'Your details and recent health history.', 'monitor_heart', 1, true),
  (2, 'Dietary behaviours and food security', 'Think about the last 7 days. Each question shows what one serving looks like.', 'restaurant', 2, true),
  (3, 'Academic workload and time pressure', 'How study fits around the rest of life.', 'school', 3, true),
  (4, 'Emotional well-being and stress', 'How you have been feeling. These are screening questions, not a diagnosis.', 'psychology', 4, true),
  (5, 'Sleep and daily routines', 'Rest and the rhythm of your days.', 'bedtime', 5, true),
  (6, 'Physical activity and sedentary behaviour', 'Moving and sitting through the week.', 'directions_walk', 6, true),
  (7, 'Financial and living conditions', 'Where you stay and how money affects health.', 'savings', 7, true),
  (8, 'Social environment and personal support', 'The people around you.', 'diversity_3', 8, true),
  (9, 'Campus environment and access to services', 'Food, spaces and health services on campus.', 'local_hospital', 9, true),
  (10, 'Student voice and institutional priorities', 'What the university should do next.', 'campaign', 10, true),
  (11, 'Clinical measurements', 'Your latest measured values. Skip any you do not have.', 'stethoscope', 11, true)
on conflict (id) do update set title = excluded.title, blurb = excluded.blurb, icon = excluded.icon, position = excluded.position;

