-- ---------------------------------------------------------------------------
-- 2. Round names
-- ---------------------------------------------------------------------------
update public.assessment_windows
set term = replace(replace(term, 'Fall Term', 'Year End Assessment'), 'Spring Term', 'Mid Year Assessment'),
    title = case when title ilike 'fall%' then 'Year End Health Assessment' when title ilike 'spring%' then 'Mid Year Health Assessment' else title end
where term ilike any (array['%fall%', '%spring%']) or title ilike any (array['%fall%', '%spring%']);
update public.notifications
